    (1, 5498, 'MANITOL AL 25 % FRASCO DE 50 ML', 13, '1010501001', '4010101001', 1),
    (1, 5499, 'MANZANA EXPORT FRASCO 115G *', 13, '1010501001', '4010101001', 1),
